from typing import List, Optional

def binary_search(arr: List[int], target: int) -> int:
    """
    Search for target in a sorted array using binary search.
    Returns the index of the target if found, or -1 if not present.
    Time complexity must be O(log n) - no linear scans allowed.
    """
    left, right = 0, len(arr) - 1
    while left <= right:
        mid = (left + right) // 2
        if arr[mid] == target:
            return mid
        elif arr[mid] < target:
            left = mid + 1
        else:
            right = mid - 1
    return -1


